styl:
.b-new-hero-16 u + .body .gmail-blend-screen {  background: #000;
  mix-blend-mode: screen;  }
.b-new-hero-16 u + .body .gmail-blend-diff {  background: #000;
  mix-blend-mode: difference;  }
.bgr-image.b-new-hero-16 {  background: url("https://fsms.quadcode.com/storage/public/d6/pd/13js2mcraq8anafg/2-1-3-head.png") center top no-repeat;
  background-size: cover;
  background-color: #000;  }
.brad-full.b-new-hero-16 {  border-radius: 32px !important;  }
.b-new-hero-16 .white-title {  font-family: Helvetica !important;
  font-weight: 700;
  font-size: 42px;
  line-height: 52px;
  color: #f9f9f9;
  word-break: break-word;  }
@media screen and (max-width: 600px) {
  .b-new-hero-16 .white-title {  font-size: 26px !important;
    line-height: 32px !important;  }
}
.b-new-hero-16 .white-text {  font-family: Helvetica !important;
  font-style: normal;
  font-weight: 400;
  font-size: 18px;
  line-height: 27px;
  color: #fff;  }
.b-new-hero-16 .pb8 {  padding-bottom: 8px;  }
.b-new-hero-16 .pb16 {  padding-bottom: 16px;  }
.b-new-hero-16 .h-406 {  font-size: 0;
  line-height: 310px;
  height: 310px;  }
@media screen and (max-width: 500px) {
  .b-new-hero-16 .h-406 {  line-height: 240px !important;
    height: 240px !important;  }
}
.b-new-hero-16 u+.body .gmail-blend-screen {  background:#000;mix-blend-mode:screen  }
.b-new-hero-16 u+.body .gmail-blend-diff {  background:#000;mix-blend-mode:difference  }
